import random
import struct
from typing import List

# Generator for OSC packet buffers tailored to sc_msg_iter usage in the fuzz stubs.
# Produces valid OSC-encoded buffers with or without a type tag string.
# Covers tags: i, f, d, s, b, m, t. Respects big-endian and 4-byte padding.

MAX_SIZE = 4096
TAG_SET = [b'i', b'f', b'd', b's', b'b', b'm', b't']


def _pad4(n: int) -> int:
    r = n & 3
    return 0 if r == 0 else 4 - r


def _osc_string_bytes(s: bytes) -> bytes:
    b = s + b"\x00"
    b += b"\x00" * _pad4(len(b))
    return b


def _rand_ascii(rng: random.Random, min_len: int, max_len: int) -> bytes:
    length = rng.randint(min_len, max_len)
    alphabet = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789 _-./:@[]{}()!?,+*"
    return bytes(rng.choice(alphabet) for _ in range(length))


def _be_u32(v: int) -> bytes:
    return struct.pack("!I", v & 0xFFFFFFFF)


def _be_i32(v: int) -> bytes:
    # Clamp into 32-bit signed range to avoid struct errors
    if v > 0x7FFFFFFF:
        v = 0x7FFFFFFF
    if v < -0x80000000:
        v = -0x80000000
    return struct.pack("!i", int(v))


def _be_f32(x: float) -> bytes:
    return struct.pack("!f", float(x))


def _be_f64(x: float) -> bytes:
    return struct.pack("!d", float(x))


def _be_i64(v: int) -> bytes:
    # Clamp into 64-bit signed range to avoid struct errors
    if v > 0x7FFFFFFFFFFFFFFF:
        v = 0x7FFFFFFFFFFFFFFF
    if v < -0x8000000000000000:
        v = -0x8000000000000000
    return struct.pack("!q", int(v))


def _build_arg_for_tag(rng: random.Random, tag: bytes) -> bytes:
    t = tag
    if t == b'i':  # int32 big-endian
        choices = [0, 1, -1, 0x7FFFFFFF, -0x80000000, rng.randint(-0x80000000, 0x7FFFFFFF)]
        return _be_i32(rng.choice(choices))
    if t == b'f':  # float32 big-endian
        choices = [0.0, -0.0, 1.0, -1.0, 440.0, 1e-6, 1e6, 3.14159265, -2.7182818]
        x = rng.uniform(-1e6, 1e6) if rng.random() < 0.5 else rng.choice(choices)
        return _be_f32(x)
    if t == b'd':  # float64 big-endian
        x = rng.uniform(-1e12, 1e12) if rng.random() < 0.5 else rng.choice([0.0, 1.0, -1.0, 1e-12, 1e12, 2.0 ** 40, -2.0 ** 40])
        return _be_f64(x)
    if t == b's':  # OSC string
        raw = b"" if rng.random() < 0.2 else _rand_ascii(rng, 1, 32)
        return _osc_string_bytes(raw)
    if t == b'b':  # blob
        length = rng.randint(0, 64)
        if hasattr(rng, 'randbytes'):
            data = rng.randbytes(length)
        else:
            data = bytes(rng.getrandbits(8) for _ in range(length))
        out = _be_u32(length) + data
        out += b"\x00" * _pad4(len(out))
        return out
    if t == b'm':  # MIDI 4 bytes
        status_nibbles = [0x80, 0x90, 0xA0, 0xB0, 0xC0, 0xD0, 0xE0]
        status = (rng.choice(status_nibbles) | rng.randint(0, 15)) & 0xFF
        data1 = rng.randint(0, 127)
        data2 = rng.randint(0, 127)
        data3 = rng.randint(0, 127)
        return bytes([status, data1, data2, data3])
    if t == b't':  # time tag: 64-bit big-endian signed (iterator treats as int64)
        # Compose a value strictly within signed 64-bit range
        if rng.random() < 0.5:
            v = rng.randint(0, 0x7FFFFFFFFFFFFFFF)
        else:
            hi = rng.randint(0, 0x7FFFFFFF)  # ensure sign bit not set to stay within signed range
            lo = rng.randint(0, 0xFFFFFFFF)
            v = (hi << 32) | lo
        return _be_i64(v)
    return b""


def _build_with_tags(rng: random.Random) -> bytes:
    ntags = rng.randint(1, 5)
    tags: List[bytes] = [rng.choice(TAG_SET) for _ in range(ntags)]
    tag_str = b"," + b"".join(tags) + b"\x00"
    tag_str += b"\x00" * _pad4(len(tag_str))
    payload = b"".join(_build_arg_for_tag(rng, t) for t in tags)
    out = tag_str + payload
    if len(out) > MAX_SIZE:
        while tags and len(out) > MAX_SIZE:
            tags = tags[:-1]
            tag_str = b"," + b"".join(tags) + b"\x00"
            tag_str += b"\x00" * _pad4(len(tag_str))
            payload = b"".join(_build_arg_for_tag(rng, t) for t in tags)
            out = tag_str + payload
        if not tags:
            out = _build_minimal_with_single_tag(rng)
    return out


def _build_minimal_with_single_tag(rng: random.Random) -> bytes:
    tag = rng.choice(TAG_SET)
    tag_str = b"," + tag + b"\x00"
    tag_str += b"\x00" * _pad4(len(tag_str))
    payload = _build_arg_for_tag(rng, tag)
    return tag_str + payload


def _build_untagged(rng: random.Random) -> bytes:
    choice = rng.choice([b"i", b"f", b"d", b"t", b"m", b"s", b"b"])  # bytes for reuse
    return _build_arg_for_tag(rng, choice)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    if rng.random() < 0.75:
        if rng.random() < 0.6:
            buf = _build_with_tags(rng)
        else:
            buf = _build_minimal_with_single_tag(rng)
    else:
        buf = _build_untagged(rng)

    if len(buf) > MAX_SIZE:
        buf = buf[:MAX_SIZE]
    return bytes(buf)
